def apply_size_filter(grid, min_size=4):
    """Keep only components larger than min_size"""
    result = np.zeros_like(grid)
    visited = np.zeros_like(grid)
    rows, cols = grid.shape

    for r in range(rows):
        for c in range(cols):
            if grid[r, c] != 0 and not visited[r, c]:  # Skip 0s for now
                color = grid[r, c]
